 		recordDependencyOnCurrentExtension(&myself, false);

 		if (reloftypeid)
@@ -1391,18 +1394,6 @@ heap_create_with_catalog(const char *relname,
 			referenced.objectSubId = 0;
 			recordDependencyOn(&myself, &referenced, DEPENDENCY_NORMAL);
